-- P2 runtime hardening for MAT-FUNC-049/050. Published snapshots only,
-- replay before mutable-state checks, and bounded/serialized generation.

create or replace function private.clone_request_core(p_source_request_id uuid,p_scheduled_on date,p_actor uuid,p_reason text,p_provenance boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare sr public.service_requests%rowtype;sv public.service_request_versions%rowtype;csv public.catalog_service_versions%rowtype;qv public.questionnaire_versions%rowtype;q public.questionnaires%rowtype;nr uuid:=extensions.gen_random_uuid();nv uuid:=extensions.gen_random_uuid();h text;
begin
 select*into sr from public.service_requests where id=p_source_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,p_actor)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;
 select*into sv from public.service_request_versions where id=sr.current_version_id and request_id=sr.id;if not found then raise exception'SOURCE_REQUEST_VERSION_MISSING'using errcode='55000';end if;
 select csv.* into csv from public.catalog_services cs join public.catalog_service_versions csv on csv.id=cs.current_published_version_id and csv.service_id=cs.id and csv.library_id=cs.library_id where cs.id=sr.service_id and cs.library_id=sr.library_id and cs.status='PUBLISHED'and csv.status='PUBLISHED';if not found then raise exception'SERVICE_VERSION_NOT_PUBLISHED'using errcode='55000';end if;
 if sr.questionnaire_version_id is not null then select*into q from public.questionnaires where library_id=sr.library_id and status='PUBLISHED'and current_published_version_id=sr.questionnaire_version_id;if not found then raise exception'QUESTIONNAIRE_VERSION_NOT_APPROVED_ACTIVE'using errcode='55000';end if;select*into qv from public.questionnaire_versions where id=sr.questionnaire_version_id and questionnaire_id=q.id and library_id=q.library_id and status='PUBLISHED'and translation_review_status='APPROVED';if not found then raise exception'QUESTIONNAIRE_VERSION_NOT_APPROVED_ACTIVE'using errcode='55000';end if;end if;
 h:=private.canonical_request_hash(jsonb_build_object('request_id',nr,'version',1,'source_request_id',sr.id,'catalog_hash',csv.content_hash,'questionnaire_hash',coalesce(qv.snapshot_hash,repeat('0',64)),'scheduled_on',p_scheduled_on));
 insert into public.service_requests(id,client_organization_id,site_id,library_id,service_id,questionnaire_version_id,status,created_by)values(nr,sr.client_organization_id,sr.site_id,sr.library_id,sr.service_id,qv.id,'DRAFT',p_actor);
 insert into public.service_request_versions(id,request_id,client_organization_id,library_id,version_number,description,urgency,desired_date,budget_minor,currency_code,required_quote_data,required_fields_complete,catalog_snapshot_hash,questionnaire_snapshot_hash,change_reason,content_hash,created_by)values(nv,nr,sr.client_organization_id,sr.library_id,1,sv.description,sv.urgency,coalesce(p_scheduled_on,sv.desired_date),sv.budget_minor,sv.currency_code,sv.required_quote_data,sv.required_fields_complete,csv.content_hash,coalesce(qv.snapshot_hash,repeat('0',64)),p_reason,h,p_actor);
 update public.service_requests set current_version_id=nv where id=nr;
 if p_provenance then insert into public.service_request_clone_provenance(client_organization_id,source_request_id,source_request_version_id,cloned_request_id,cloned_request_version_id,source_catalog_snapshot_hash,revalidated_catalog_snapshot_hash,source_questionnaire_snapshot_hash,revalidated_questionnaire_snapshot_hash,created_by)values(sr.client_organization_id,sr.id,sv.id,nr,nv,sv.catalog_snapshot_hash,csv.content_hash,sv.questionnaire_snapshot_hash,coalesce(qv.snapshot_hash,repeat('0',64)),p_actor);end if;
 return jsonb_build_object('request_id',nr,'request_version_id',nv,'status','DRAFT','catalog_snapshot_hash',csv.content_hash,'questionnaire_snapshot_hash',coalesce(qv.snapshot_hash,repeat('0',64)));
end$$;

create or replace function public.clone_service_request(p_source_request_id uuid,p_desired_date date,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();sr public.service_requests%rowtype;h text;r jsonb;
begin
 select*into sr from public.service_requests where id=p_source_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,a)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;
 if length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_CLONE_COMMAND'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','rfq.request.clone.v2','source',p_source_request_id,'desired_date',p_desired_date,'reason',btrim(p_change_reason)));r:=private.begin_contract_command(sr.client_organization_id,'rfq.request.clone.v2',p_idempotency_key,h,a);if r is not null then return r;end if;
 r:=private.clone_request_core(p_source_request_id,p_desired_date,a,btrim(p_change_reason),true)||jsonb_build_object('outcome','SERVICE_REQUEST_CLONED','source_request_id',p_source_request_id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sr.client_organization_id,a,'USER','rfq.request.cloned','service_request',r->>'request_id',p_correlation_id,jsonb_build_object('source_request_id',p_source_request_id,'revalidated',true,'published_only',true),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sr.client_organization_id,'service_request',r->>'request_id','ServiceRequestClonedV2',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(sr.client_organization_id,'rfq.request.clone.v2',p_idempotency_key,r);return r;
end$$;

create or replace function public.create_recurring_service_plan(p_template_request_id uuid,p_cadence text,p_starts_on date,p_ends_on date,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();sr public.service_requests%rowtype;cv public.catalog_service_versions%rowtype;h text;r jsonb;pid uuid:=extensions.gen_random_uuid();vid uuid:=extensions.gen_random_uuid();
begin
 select*into sr from public.service_requests where id=p_template_request_id;if not found or not private.can_manage_client_request(sr.client_organization_id,a)then raise exception'REQUEST_SCOPE_DENIED'using errcode='42501';end if;
 if p_cadence not in('MONTHLY','QUARTERLY','ANNUALLY')or p_starts_on is null or(p_ends_on is not null and p_ends_on<p_starts_on)or length(btrim(coalesce(p_reason,'')))not between 3 and 500 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_RECURRING_PLAN'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.plan.create.v2','template',p_template_request_id,'cadence',p_cadence,'starts_on',p_starts_on,'ends_on',p_ends_on,'reason',btrim(p_reason)));r:=private.begin_contract_command(sr.client_organization_id,'recurring.plan.create.v2',p_idempotency_key,h,a);if r is not null then return r;end if;
 select cv.*into cv from public.catalog_services cs join public.catalog_service_versions cv on cv.id=cs.current_published_version_id and cv.service_id=cs.id where cs.id=sr.service_id and cs.library_id=sr.library_id and cs.status='PUBLISHED'and cv.status='PUBLISHED'and cv.recurring_eligible;if not found then raise exception'SERVICE_NOT_RECURRING_ELIGIBLE'using errcode='22023';end if;
 insert into public.recurring_service_plans(id,client_organization_id,template_request_id,created_by)values(pid,sr.client_organization_id,p_template_request_id,a);insert into public.recurring_service_plan_versions(id,plan_id,version_number,cadence,starts_on,ends_on,status,reason,created_by)values(vid,pid,1,p_cadence,p_starts_on,p_ends_on,'ACTIVE',btrim(p_reason),a);
 r:=jsonb_build_object('outcome','RECURRING_PLAN_CREATED','plan_id',pid,'plan_version_id',vid,'status','ACTIVE');insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(sr.client_organization_id,a,'USER','recurring.plan.created','recurring_service_plan',pid::text,p_correlation_id,jsonb_build_object('cadence',p_cadence,'template_request_id',p_template_request_id,'published_service_version_id',cv.id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(sr.client_organization_id,'recurring_service_plan',pid::text,'RecurringServicePlanCreatedV2',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(sr.client_organization_id,'recurring.plan.create.v2',p_idempotency_key,r);return r;
end$$;

create or replace function public.transition_recurring_service_plan(p_plan_id uuid,p_action text,p_reason text,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.recurring_service_plans%rowtype;v public.recurring_service_plan_versions%rowtype;ns text;h text;r jsonb;nvid uuid:=extensions.gen_random_uuid();
begin
 perform pg_advisory_xact_lock(hashtextextended('recurring-plan:'||p_plan_id::text,0));select*into p from public.recurring_service_plans where id=p_plan_id for update;if not found or not private.can_manage_client_request(p.client_organization_id,a)then raise exception'RECURRING_PLAN_SCOPE_DENIED'using errcode='42501';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.plan.transition.v2','plan',p.id,'action',p_action,'expected',p_expected_row_version,'reason',btrim(p_reason)));r:=private.begin_contract_command(p.client_organization_id,'recurring.plan.transition.v2',p_idempotency_key,h,a);if r is not null then return r;end if;
 ns:=case p_action when'PAUSE'then'PAUSED'when'RESUME'then'ACTIVE'when'END'then'ENDED'else null end;if ns is null or p.status='ENDED'or(p.status='ACTIVE'and p_action not in('PAUSE','END'))or(p.status='PAUSED'and p_action not in('RESUME','END'))or p.row_version<>p_expected_row_version or length(btrim(coalesce(p_reason,'')))not between 3 and 500 then raise exception'INVALID_RECURRING_TRANSITION'using errcode='55000';end if;
 select*into v from public.recurring_service_plan_versions where plan_id=p.id and version_number=p.current_version;if not found then raise exception'RECURRING_PLAN_VERSION_MISSING'using errcode='55000';end if;
 insert into public.recurring_service_plan_versions(id,plan_id,version_number,cadence,starts_on,ends_on,status,reason,created_by)values(nvid,p.id,p.current_version+1,v.cadence,v.starts_on,case when ns='ENDED'then greatest(v.starts_on,least(coalesce(v.ends_on,current_date),current_date))else v.ends_on end,ns,btrim(p_reason),a);update public.recurring_service_plans set status=ns,current_version=current_version+1,row_version=row_version+1,updated_at=clock_timestamp()where id=p.id;
 r:=jsonb_build_object('outcome','RECURRING_PLAN_'||ns,'plan_id',p.id,'plan_version_id',nvid,'status',ns,'row_version',p.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.client_organization_id,a,'USER','recurring.plan.'||lower(p_action),'recurring_service_plan',p.id::text,p_correlation_id,jsonb_build_object('from_status',p.status,'to_status',ns,'reason',btrim(p_reason)),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.client_organization_id,'recurring_service_plan',p.id::text,'RecurringServicePlan'||initcap(lower(ns))||'V2',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p.client_organization_id,'recurring.plan.transition.v2',p_idempotency_key,r);return r;
end$$;

create or replace function public.generate_recurring_service_requests(p_plan_id uuid,p_through_date date,p_max_occurrences integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();p public.recurring_service_plans%rowtype;v public.recurring_service_plan_versions%rowtype;h text;r jsonb;d date;generated int:=0;iterations int:=0;x jsonb;months int;
begin
 perform pg_advisory_xact_lock(hashtextextended('recurring-plan:'||p_plan_id::text,0));select*into p from public.recurring_service_plans where id=p_plan_id for update;if not found or not private.can_manage_client_request(p.client_organization_id,a)then raise exception'RECURRING_PLAN_SCOPE_DENIED'using errcode='42501';end if;
 h:=private.canonical_request_hash(jsonb_build_object('operation','recurring.generate.v2','plan',p.id,'through',p_through_date,'max',p_max_occurrences));r:=private.begin_contract_command(p.client_organization_id,'recurring.generate.v2',p_idempotency_key,h,a);if r is not null then return r;end if;
 if p.status<>'ACTIVE'then raise exception'RECURRING_PLAN_NOT_ACTIVE'using errcode='55000';end if;if p_max_occurrences not between 1 and 24 or p_through_date<current_date or p_through_date>current_date+366 then raise exception'RECURRING_GENERATION_BOUNDS_EXCEEDED'using errcode='22023';end if;
 select*into v from public.recurring_service_plan_versions where plan_id=p.id and version_number=p.current_version and status='ACTIVE';if not found then raise exception'RECURRING_PLAN_VERSION_NOT_ACTIVE'using errcode='55000';end if;months:=case v.cadence when'MONTHLY'then 1 when'QUARTERLY'then 3 when'ANNUALLY'then 12 else null end;if months is null then raise exception'INVALID_RECURRING_CADENCE'using errcode='55000';end if;
 d:=v.starts_on;while d<=p_through_date and(v.ends_on is null or d<=v.ends_on)and generated<p_max_occurrences and iterations<24 loop iterations:=iterations+1;if not exists(select 1 from public.recurring_service_occurrences where plan_id=p.id and scheduled_on=d)then x:=private.clone_request_core(p.template_request_id,d,a,'Génération prestation récurrente',false);insert into public.recurring_service_occurrences(plan_id,plan_version_id,client_organization_id,scheduled_on,generated_request_id,generated_request_version_id)values(p.id,v.id,p.client_organization_id,d,(x->>'request_id')::uuid,(x->>'request_version_id')::uuid);generated:=generated+1;end if;d:=(d+make_interval(months=>months))::date;end loop;
 if iterations>=24 and d<=p_through_date and(v.ends_on is null or d<=v.ends_on)and generated<p_max_occurrences then raise exception'RECURRING_TOTAL_ITERATION_LIMIT_REACHED'using errcode='22023';end if;
 r:=jsonb_build_object('outcome','RECURRING_REQUESTS_GENERATED','plan_id',p.id,'plan_version_id',v.id,'generated_count',generated,'iteration_count',iterations,'through_date',p_through_date,'horizon_days',p_through_date-current_date,'autonomous_invitations',false,'autonomous_spend',false);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.client_organization_id,a,'USER','recurring.requests.generated','recurring_service_plan',p.id::text,p_correlation_id,jsonb_build_object('generated_count',generated,'iteration_count',iterations,'through_date',p_through_date,'plan_version_id',v.id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.client_organization_id,'recurring_service_plan',p.id::text,'RecurringServiceRequestsGeneratedV2',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p.client_organization_id,'recurring.generate.v2',p_idempotency_key,r);return r;
end$$;

revoke all on function private.clone_request_core(uuid,date,uuid,text,boolean),public.clone_service_request(uuid,date,text,text,uuid),public.create_recurring_service_plan(uuid,text,date,date,text,text,uuid),public.transition_recurring_service_plan(uuid,text,text,integer,text,uuid),public.generate_recurring_service_requests(uuid,date,integer,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.clone_service_request(uuid,date,text,text,uuid),public.create_recurring_service_plan(uuid,text,date,date,text,text,uuid),public.transition_recurring_service_plan(uuid,text,text,integer,text,uuid),public.generate_recurring_service_requests(uuid,date,integer,text,uuid)to authenticated;
notify pgrst,'reload schema';
